 return '<main id="main" class="presentation"><header class="projection-header"><span class="projection-brand">PRACTICAL AI <small>FOR PROFESSIONALS</small></span><span>SESSION '+String((p.session||0)+1).padStart(2,'0')+' / 08</span><img class="costaatt-logo" src="/assets/costaatt-logo.webp" alt="COSTAATT" width="474" height="474"></header><section class="projection-stage"><p class="eyebrow">'+esc(s.title)+' · '+(p.mode==='reveal'?'COMPARE YOUR REASONING':p.mode==='discussion'?'LET’S TALK':'YOUR TURN')+'</p><h1>'+(p.mode==='discussion'?'What did you notice?':p.mode==='reveal'?'A useful approach.':esc(a.title))+'</h1>'+(p.mode==='timer'?'<p class="projection-task">'+esc(a.instructions)+'</p>'+timer('projector',a.seconds,true):p.mode==='discussion'?'<ol class="projection-questions">'+a.discussion.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>':p.mode==='reveal'?'<div class="projection-text preserve">'+esc(a.reveal)+'</div>':'<p class="projection-task">'+esc(a.instructions)+'</p><div class="projection-text preserve">'+esc(a.raw)+'</div>')+'</section><footer class="projection-footer"><span>AI suggests. You decide.</span><span class="projection-copyright">© '+COPYRIGHT_YEAR+' COSTAATT. All rights reserved. · Designed by the Technology Services Department.</span><div>'+controls+'<a class="button" href="#facilitator">Exit presentation</a></div></footer></main>';
