function workbookLabel(key){return key.replaceAll('.',' / ').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());}
function workbookValue(value){if(value===true)return 'Yes';if(value===false)return 'No';return String(value??'').trim();}
function workbookPrintHtml(){const p=state.profile||{};const completedRows=content.sessions.map((s,i)=>'<tr><th scope="row">'+String(i+1).padStart(2,'0')+'</th><td>'+esc(s.title)+'</td><td>'+esc(s.goal)+'</td><td>'+(state.completed.includes(i)?'<span class="status-complete">Complete</span>':'<span class="status-open">Open</span>')+'</td></tr>').join('');const notes=Object.entries(state.answers).filter(([k,v])=>v!==''&&!k.startsWith('profile.')&&k!=='game.index'&&!k.startsWith('checklist.')).map(([k,v])=>'<section class="workbook-note"><h3>'+esc(workbookLabel(k))+'</h3><div class="preserve">'+esc(workbookValue(v))+'</div></section>').join('')||'<p class="muted">No written notes saved yet.</p>';const checklist=content.checklist.map((item,i)=>'<li class="'+(answer('checklist.'+i)?'checked':'')+'">'+(answer('checklist.'+i)?'✓ ':'☐ ')+esc(item)+'</li>').join('');const toolkit=content.templates.map((t,i)=>'<section class="toolkit-card"><p class="eyebrow">TEMPLATE '+String(i+1).padStart(2,'0')+'</p><h3>'+esc(t.name)+'</h3><pre>'+esc(templateText(i))+'</pre></section>').join('');const score=Object.entries(state.game).filter(([i,a])=>content.trust[i]?.answer===a).length;return '<div class="workbook-cover"><img class="workbook-logo" src="/assets/costaatt-logo.webp" alt="COSTAATT"><p class="eyebrow">PARTICIPANT WORKBOOK</p><h1>Practical AI for Professionals</h1><p class="workbook-subtitle">A one-day applied workshop for better prompts, useful workflows and responsible decisions.</p><div class="workbook-meta"><div><span>PARTICIPANT</span><strong>'+esc(p.name||'Participant')+'</strong></div><div><span>ROLE</span><strong>'+esc(p.role||'Not provided')+'</strong></div><div><span>ORGANISATION</span><strong>'+esc(p.org||'Not provided')+'</strong></div><div><span>FOCUS</span><strong>'+esc(p.focus||'Practical workplace AI')+'</strong></div><div><span>DATE</span><strong>14 January 2027</strong></div></div><div class="workbook-cover-footer">Your mission: ' + esc(p.task||'Bring one real task into the workshop.') + '<br>Designed by the Technology Services Department · COSTAATT</div></div><section class="workbook-section"><p class="eyebrow">YOUR MISSION</p><h2>Where you started.</h2><div class="workbook-output mission-record"><p><strong>Starting task</strong><br>'+esc(p.task||'Bring one real task into the workshop.')+'</p><p><strong>Workshop focus</strong><br>'+esc(p.focus||'Practical workplace AI')+'</p></div></section><section class="workbook-section"><p class="eyebrow">YOUR PROGRESS</p><h2>Eight sessions. Real work.</h2><p>You completed '+state.completed.length+' of 8 sessions. Use this record to revisit your decisions and continue the work.</p><table class="workbook-table"><thead><tr><th scope="col">No.</th><th scope="col">Session</th><th scope="col">Focus</th><th scope="col">Status</th></tr></thead><tbody>'+completedRows+'</tbody></table></section><section class="workbook-section"><p class="eyebrow">YOUR NOTES</p><h2>What you worked through.</h2>'+notes+'</section><section class="workbook-section"><p class="eyebrow">RESPONSIBLE AI CHECKLIST</p><h2>Before you trust an output.</h2><ul class="workbook-checklist">'+checklist+'</ul><p class="small muted">Trust game score: '+score+' sound calls across '+Object.keys(state.game).length+' scenarios explored.</p></section><section class="workbook-section"><p class="eyebrow">REUSABLE AI ASSISTANT</p><h2>Your working brief.</h2><div class="workbook-output preserve">'+esc(assistantText())+'</div></section><section class="workbook-section"><p class="eyebrow">ACTION PLAN</p><h2>Take the work forward.</h2><div class="workbook-output preserve">'+esc(planText())+'</div></section><section class="workbook-section workbook-toolkit"><p class="eyebrow">TAKE-HOME TOOLKIT</p><h2>Prompt templates for Monday.</h2>'+toolkit+'</section><footer class="workbook-footer">© '+COPYRIGHT_YEAR+' COSTAATT. All rights reserved. · Designed by the Technology Services Department.</footer>';
}
function certificateHtml(){const p=state.profile||{};const date=new Date().toLocaleDateString('en-TT',{year:'numeric',month:'long',day:'numeric'});return '<div class="certificate-page"><div class="certificate-inner"><img class="certificate-logo" src="/assets/costaatt-logo.webp" alt="COSTAATT"><p class="certificate-kicker">CERTIFICATE OF COMPLETION</p><h1>Practical AI for Professionals</h1><div class="certificate-rule"></div><p class="certificate-text">This certificate recognises</p><h2>'+esc(p.name||'Participant')+'</h2><p class="certificate-text">for marking all eight sessions complete in the COSTAATT Practical AI for Professionals workshop.</p><p class="certificate-evidence">Participant-marked completion. Attendance is not independently verified.</p><div class="certificate-details"><div><span>COMPLETED</span><strong>'+esc(date)+'</strong></div><div><span>FOCUS</span><strong>'+esc(p.focus||'Practical workplace AI')+'</strong></div></div><p class="certificate-facilitators">Facilitated by Kevin Ramsoobhag and Darren Headley</p><div class="certificate-footer">© '+COPYRIGHT_YEAR+' COSTAATT. All rights reserved.<br>Designed by the Technology Services Department.</div></div></div>';}
function printWorkbook(){$('#print-area').className='print-workbook';$('#print-area').innerHTML=workbookPrintHtml();window.print();}
function printCertificate(){if(state.completed.length!==8){toast('Complete all eight sessions to unlock your certificate.');return;}$('#print-area').className='print-certificate';$('#print-area').innerHTML=certificateHtml();window.print();}
function workbookText(){return `PRACTICAL AI FOR PROFESSIONALS\nParticipant workbook · 14 January 2027\n\n${state.profile?state.profile.name+' · '+state.profile.role:''}\nSessions complete: ${state.completed.map(i=>content.sessions[i].title).join(', ')||'None marked'}\n\n`+Object.entries(state.answers).filter(([k,v])=>v!==''&&!k.startsWith('profile.')&&k!=='game.index').map(([k,v])=>k.replaceAll('.',' / ').toUpperCase()+'\n'+String(v)).join('\n\n')+'\n\n'+assistantText()+'\n\n'+planText();}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your download is ready.');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied. Ready for your AI tool.');}catch{const box=document.createElement('textarea');box.value=text;box.style.cssText='position:fixed;top:0;left:0;opacity:0';document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();toast(ok?'Copied.':'Copy unavailable. Select the text and copy manually.');}}
function copyValue(key){const [kind,id]=key.split(':');if(kind==='opening')return content.sessions[0].raw;if(kind==='prompt')return promptText();if(kind==='assistant')return assistantText();if(kind==='plan')return planText();if(kind==='template')return templateText(Number(id));if(kind==='final')return content.sessions[6].instructions+'\n\n'+content.finalPack.map(x=>x.name.toUpperCase()+'\n'+x.text).join('\n\n')+'\n\nDELIVERABLES\n'+content.deliverables.join('\n');if(kind==='challenge'){const c=content.productivity.find(x=>x.id===id);return c.scenario+'\n\n'+c.raw+'\n\nTASK\n'+c.objective;}if(kind==='lab'){const c=content.labs.find(x=>x.id===id);return c.task+'\n\n'+c.raw+(id==='data'?'\n\n'+content.dataset.map(r=>r.join(',')).join('\n'):'');}return '';}
function printText(title,text){$('#print-area').className='';$('#print-area').innerHTML=`<img class="print-logo" src="/assets/costaatt-logo.webp" alt="COSTAATT"><h1>${esc(title)}</h1><div class="preserve">${esc(text)}</div>`;window.print();}
function refreshOutputs(){[['prompt',promptText],['assistant',assistantText],['plan',planText]].forEach(([key,fn])=>{const el=$(`[data-output="${key}"]`);if(el)el.textContent=fn();});document.querySelectorAll('[data-time-result]').forEach(el=>el.innerHTML=timeResult(el.dataset.timeResult));}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){state.answers[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.field==='profile.consent')state.consent=el.checked;save({participant:el.dataset.field==='profile.consent'});refreshOutputs();}});
document.addEventListener('toggle',e=>{if(e.target.dataset.reveal){state.reveals[e.target.dataset.reveal]=e.target.open;save();}},true);
document.addEventListener('submit',e=>{if(e.target.id==='join-form'){e.preventDefault();const keys=['name','role','task'];if(keys.some(k=>!answer('profile.'+k).trim())){toast('Add your first name, role and starting task.');return;}state.profile={name:answer('profile.name').trim(),role:answer('profile.role').trim(),org:answer('profile.org').trim(),task:answer('profile.task').trim(),focus:answer('profile.focus').trim()};state.consent=state.answers['profile.consent']===true;state.participantId=state.consent?(state.participantId||((globalThis.crypto&&crypto.randomUUID)?crypto.randomUUID():null)):state.participantId;if(!answer('assistant.role'))state.answers['assistant.role']=state.profile.role;if(!answer('assistant.tasks'))state.answers['assistant.tasks']=state.profile.task;if(!answer('plan.opportunity1'))state.answers['plan.opportunity1']=state.profile.task;save({participant:true});location.hash='journey';}if(e.target.id==='content-form'){e.preventDefault();const updated=structuredClone(content);e.target.querySelectorAll('[data-edit]').forEach(el=>setPath(updated,el.dataset.edit,el.type==='number'?Number(el.value):el.value));try{if(!sameShape(updated,defaultContent))throw new Error('format');localStorage.setItem(CONTENT,JSON.stringify(updated));content=updated;render(false);toast('Activity changes saved in this browser.');}catch{$('#editor-status').textContent='Unable to save. Check the fields or export your current content pack.';}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.field&&el.type==='checkbox'&&el.dataset.field==='profile.consent'){state.consent=el.checked;save({participant:true});}if(el.dataset.field&&el.tagName==='SELECT'){state.answers[el.dataset.field]=el.value;save();}if(el.id==='assistant-example'&&el.value!==''){const example=content.assistantExamples[Number(el.value)];if(assistantFields.some(([key])=>answer('assistant.'+key))&&!confirm('Replace the current assistant fields with this example?')){el.value='';return;}for(const key of ['role','tasks','inputs','outputs','style'])state.answers['assistant.'+key]=example[key];state.answers['assistant.never']='Invent facts, make final decisions, send messages or promise approvals.';state.answers['assistant.private']='Passwords, personal records, confidential HR or customer information.';save();render(false);}if(el.id==='projection-activity'){state.projection.activity=Number(el.value);state.projection.mode='challenge';delete state.timers.projector;save({projection:true});render(false);}if(el.id==='editor-group')$('#content-fields').innerHTML=editorFields(getPath(content,el.value),el.value);if(el.id==='import-content'){try{const file=el.files[0];if(!file)return;if(file.size>2000000)throw Error('size');const imported=JSON.parse(await file.text());if(!sameShape(imported,defaultContent))throw Error('shape');if(!confirm('Replace the workshop content in this browser with the imported pack?'))return;localStorage.setItem(CONTENT,JSON.stringify(imported));content=imported;render(false);toast('Content pack imported.');}catch{$('#editor-status').textContent='Import failed. Choose an exported workshop content pack with all original fields.';}}});
document.addEventListener('click',e=>{const summary=e.target.closest('summary');if(summary?.parentElement?.dataset.reveal){const id=summary.parentElement.dataset.reveal;state.reveals[id]=!state.reveals[id];save();}const copy=e.target.closest('[data-copy]');if(copy){copyText(copyValue(copy.dataset.copy));return;}const el=e.target.closest('[data-action]');if(!el)return;const {action,key,index}=el.dataset;const i=Number(index);if(action.startsWith('timer-')){timerAction(key,Number(el.dataset.seconds),action==='timer-reset');return;}if(action==='refresh-reporting'){loadReporting();}else if(action==='start-projection-room'){startProjectionRoom();}else if(action==='end-projection-room'){endProjectionRoom();}else if(action==='copy-projection-room'){copyText(presentationRoomLink());}else if(action==='clear-reporting'){clearReporting();}else if(action==='toolkit-filter'){document.querySelectorAll('.filter-chip').forEach(button=>button.classList.toggle('selected',button.dataset.key===key));document.querySelectorAll('[data-filter-section]').forEach(section=>section.classList.toggle('filter-hidden',key!=='all'&&section.dataset.filterSection!==key));}else if(action==='facilitator-pulse'){state.facilitatorPulse=key;save();render(false);}else if(action==='complete'){state.completed=state.completed.includes(i)?state.completed.filter(x=>x!==i):[...state.completed,i];save({participant:true});render(false);toast(state.completed.includes(i)?'Session complete. Keep the useful parts.':'Session marked unfinished.');}else if(action==='challenge-done'){state.challenges=state.challenges.includes(key)?state.challenges.filter(x=>x!==key):[...state.challenges,key];save({participant:true});render(false);}else if(action==='game-index'){state.answers['game.index']=Math.max(0,Math.min(content.trust.length-1,i));save();render(false);}else if(action==='game-answer'){if(state.game[i])return;state.game[i]=['USE IT','VERIFY IT','DON’T USE IT'][Number(el.dataset.choice)];save({participant:true});render(false);}else if(action==='game-retry'){if(!confirm('Reset your game responses and score? Your other workshop work will stay saved.'))return;state.game={};state.answers['game.index']=0;save({participant:true});render(false);}else if(action==='download-lab'){download(key==='data'?'workshop-service-data.csv':`workshop-${key}-brief.txt`,key==='data'?content.dataset.map(row=>row.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n'):copyValue('lab:'+key),key==='data'?'text/csv':'text/plain');}else if(action==='download-assistant')download('my-ai-assistant.txt',assistantText());else if(action==='download-plan')download('my-ai-action-plan.txt',planText());else if(action==='download-toolkit')download('practical-ai-prompt-toolkit.txt',content.templates.map((t,j)=>t.name.toUpperCase()+'\n\n'+templateText(j)).join('\n\n--------------------\n\n'));else if(action==='export-work')printWorkbook();else if(action==='print-workbook')printWorkbook();else if(action==='print-certificate')printCertificate();else if(action==='print-plan')printText('My AI Action Plan',planText());else if(action==='print-checklist')printText('Responsible AI Checklist','Practical AI for Professionals · 14 January 2027\n\nBefore using an AI output, ask:\n\n'+content.checklist.map(x=>'☐ '+x).join('\n\n')+'\n\nKeep confidential information in approved systems. Verify important claims against original sources. A human owns the final decision.');else if(action==='generate-assistant'||action==='generate-plan'){refreshOutputs();const type=action.endsWith('assistant')?'assistant':'plan';$(`[data-output="${type}"]`).scrollIntoView({behavior:'smooth',block:'center'});toast(type==='assistant'?'Instructions assembled. Review each section before use.':'Plan assembled. Save a copy before leaving.');}else if(action==='launch'){state.projection={session:i,activity:0,mode:'challenge'};delete state.timers.projector;save({projection:true});render(false);}else if(action==='project-mode'){state.projection.mode=key;save({projection:true});render(false);}else if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>toast('Use your browser’s full-screen control.'));else document.documentElement.requestFullscreen?.().catch(()=>toast('Use your browser’s full-screen control.'));}else if(action==='export-content')download('practical-ai-content.json',JSON.stringify(content,null,2),'application/json');else if(action==='reset-content'){if(!confirm('Restore all original workshop content in this browser? Export your edits first if you need them.'))return;content=structuredClone(defaultContent);try{localStorage.removeItem(CONTENT);}catch{}render(false);toast('Original workshop content restored.');}});
function render(focus=true){const route=location.hash.slice(1)||((new URLSearchParams(location.search)).has('join')?'join':'home'),[hashPath]=route.split('?'),[page,tab]=hashPath.split('/');let body;if(page==='home')body=home();else if(page==='join')body=join();else if(page==='journey')body=journey();else if(page==='resources')body=resources();else if(page==='facilitator')body=facilitator();else if(page==='reporting')body=reporting();else if(page==='present')body=presentation();else if(/^s[1-8]$/.test(page)){if(!state.profile){location.replace('#join');return;}body=sessionPage(Number(page.slice(1))-1,tab);}else body=`${header()}<main id="main" class="not-found"><h1>This workshop page is missing.</h1><a class="button primary" href="#journey">Return to your day</a></main>`;$('#app').innerHTML=body;document.body.classList.toggle('projection-active',page==='present');document.title=`${/^s[1-8]$/.test(page)?content.sessions[Number(page.slice(1))-1].title:page==='facilitator'?'Facilitator desk':page==='reporting'?'Participant reporting':page==='present'?'Presentation':page==='resources'?'Your toolkit':'Practical AI for Professionals'} · Workshop`;tick();if(page==='reporting')loadReporting();pollProjectionRoom(page);if(focus){window.scrollTo(0,0);const main=$('#main');main?.setAttribute('tabindex','-1');main?.focus({preventScroll:true});}}
window.addEventListener('hashchange',()=>render());
window.addEventListener('storage',e=>{if(e.key===STORE){const incoming=read(STORE,initialState());state={...initialState(),...incoming};if(location.hash.startsWith('#present')||location.hash==='#facilitator')render(false);else tick();}if(e.key===CONTENT){const incoming=read(CONTENT,defaultContent);if(sameShape(incoming,defaultContent)){content=incoming;render(false);}}if(e.key===REMOTE_ROOM){const incoming=e.newValue?JSON.parse(e.newValue):{id:'',expiresAt:''};remoteRoomId=incoming.id||'';remoteRoomExpiresAt=incoming.expiresAt||'';if(location.hash==='#facilitator')render(false);}});
