const agentContext=document.modelContext;
if(agentContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_workshop_progress',title:'Read workshop progress',description:'Read locally saved session completion without participant notes or personal details.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return {completedSessions:state.completed.map(i=>i+1),totalSessions:8};}},{name:'navigate_workshop_session',title:'Open a workshop session',description:'Navigate to a participant session. Registration opens first if needed. This does not complete an activity.',inputSchema:{type:'object',properties:{session:{type:'integer',minimum:1,maximum:8}},required:['session'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length!==1||!Number.isInteger(input.session)||input.session<1||input.session>8)throw Error('Session must be an integer from 1 to 8.');location.hash=state.profile?'s'+input.session:'join';render();return {route:location.hash,completed:false};}}]){try{Promise.resolve(agentContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
